{
  "format": "ui-contract-a11y-projection-draft",
  "labelSource": "Associate a stable visible label with the input through a unique id.",
  "projections": {
    "role": "switch",
    "checked": "Expose the native checked property as the on/off state.",
    "disabled": "Use the native disabled property."
  },
  "focus": "The native input owns keyboard focus. Use its Space activation and sequential Tab order. The track and thumb are hidden from assistive technology."
}

components/switch/interface.json.content:
{
  "schemaVersion": "2.1.0",
  "modules": [
    {
      "kind": "javascript-module",
      "path": "switch.js",
      "declarations": [
        {
          "kind": "class",
          "name": "Switch",
          "description": "Binary setting switch with a stable visible label.",
          "members": [
            {
              "kind": "field",
              "name": "checked",
              "type": {
                "text": "boolean"
              },
              "default": "false"
            },
            {
              "kind": "field",
              "name": "disabled",
              "type": {
                "text": "boolean"
              },
              "default": "false"
            },
            {
              "kind": "field",
              "name": "label",
              "type": {
                "text": "string"
              }
            },
            {
              "kind": "field",
              "name": "size",
              "type": {
                "text": "\"default\" | \"small\""
              },
              "default": "\"default\""
            }
          ],
          "events": [
            {
              "name": "change",
              "type": {
                "text": "Event"
              },
              "description": "Native change event. Read the updated boolean from the input target."
            }
          ]
        }
      ]
    }
  ]
}

